<script setup>
import { onMounted, onUnmounted, ref } from 'vue'
import './styles/ui-tokens.css'
import './styles/shell.css'
import './styles/forms.css'
import './styles/kfe2-shell.css'
import { kfePresentationApi } from './presentation/application/presentation-api.js'
import PerformanceModuleView from './components/PerformanceModuleView.vue'
import AdminModuleView from './components/AdminModuleView.vue'
import DayStartCard from './presentation/DayStartCard.vue'
import ShiftWaitingCard from './presentation/ShiftWaitingCard.vue'
import PersonalTripCard from './presentation/PersonalTripCard.vue'
import BusinessTripCard from './presentation/BusinessTripCard.vue'
import ShiftCard from './presentation/ShiftCard.vue'
import DayEndCard from './presentation/DayEndCard.vue'
import WorkSummaryCard from './presentation/WorkSummaryCard.vue'
import WorkOperationsCard from './presentation/WorkOperationsCard.vue'

const activeModule=ref('Work'),online=ref(typeof navigator==='undefined'?true:navigator.onLine),performanceModel=ref(null),currentWorkState=ref(null),latestWorkOdometer=ref(null),personalTripMetrics=ref(null),businessTripMetrics=ref(null),shiftMetrics=ref(null),dayEndSummary=ref(null),completedShiftSummary=ref(null),dailyOperationalReport=ref(null)
function syncRoute(){const next=location.hash.slice(1);activeModule.value=['Work','Performance','Admin'].includes(next)?next:'Work'}
async function loadPerformance(){try{performanceModel.value=await kfePresentationApi.read.getPerformance()}catch(error){performanceModel.value={error:String(error?.message||error)}}}
async function refreshWorkState(){latestWorkOdometer.value=await kfePresentationApi.read.latestWorkOdometer();const nextState=await kfePresentationApi.read.getWorkScreenState();currentWorkState.value=nextState;if(nextState==='SHIFT'){const shift=await kfePresentationApi.read.getActiveShift();const t=Date.parse(String(shift?.started_at||''));shiftMetrics.value=shift?{shiftId:shift.id,startOdometer:shift.start_odometer,startedAtEpochMs:Number.isFinite(t)?t:null}:null;personalTripMetrics.value=null;businessTripMetrics.value=null;dayEndSummary.value=null;completedShiftSummary.value=null;dailyOperationalReport.value=null}else if(nextState==='PERSONAL_TRIP'){const draft=await kfePresentationApi.read.getActiveTripDraft();const t=Date.parse(String(draft?.started_at||''));personalTripMetrics.value=draft?{startOdometer:draft.start_odometer_km,startTimeEpochMs:Number.isFinite(t)?t:null}:null;shiftMetrics.value=null;businessTripMetrics.value=null;dayEndSummary.value=null;completedShiftSummary.value=null;dailyOperationalReport.value=null}else if(nextState==='BUSINESS_TRIP'){const draft=await kfePresentationApi.read.getActiveTripDraft();const t=Date.parse(String(draft?.started_at||''));businessTripMetrics.value=draft?{startOdometer:draft.start_odometer_km,startTimeEpochMs:Number.isFinite(t)?t:null}:null;shiftMetrics.value=null;personalTripMetrics.value=null;dayEndSummary.value=null;completedShiftSummary.value=null;dailyOperationalReport.value=null}else if(nextState==='SHIFT_WAITING'||nextState==='DAY_ENDED'){dayEndSummary.value=await kfePresentationApi.read.getWorkSummary();completedShiftSummary.value=await kfePresentationApi.read.getCompletedShiftSummary();dailyOperationalReport.value=await kfePresentationApi.read.getDailyOperationalReport();shiftMetrics.value=null;personalTripMetrics.value=null;businessTripMetrics.value=null}else{shiftMetrics.value=null;personalTripMetrics.value=null;businessTripMetrics.value=null;dayEndSummary.value=null;completedShiftSummary.value=null;dailyOperationalReport.value=null}}
async function loadWorkState(){try{await refreshWorkState()}catch(error){console.error('Failed to load Work state:',error);currentWorkState.value=null;latestWorkOdometer.value=null;shiftMetrics.value=null;personalTripMetrics.value=null;businessTripMetrics.value=null;dayEndSummary.value=null;completedShiftSummary.value=null;dailyOperationalReport.value=null}}
async function refreshAll(){await Promise.all([loadPerformance(),refreshWorkState()])}
async function handleStartDay(odometer){try{await kfePresentationApi.commands.startDay({odometer});await refreshAll()}catch(error){console.error('Failed to start day:',error)}}
async function handleStartShift(){try{const latest=await kfePresentationApi.read.latestWorkOdometer();const odometer=Number(latest?.odometer);if(!Number.isFinite(odometer)||odometer<0)throw new Error('Authoritative start odometer is unavailable');await kfePresentationApi.commands.startShift({startOdometer:odometer});await refreshWorkState()}catch(error){console.error('Failed to start shift:',error)}}
async function handleStartBusinessTrip(){try{const latest=await kfePresentationApi.read.latestWorkOdometer();const odometer=Number(latest?.odometer);if(!Number.isFinite(odometer)||odometer<0)throw new Error('Authoritative start odometer is unavailable');await kfePresentationApi.commands.startTrip({trip_type:'BUSINESS',start_odometer_km:odometer});await refreshWorkState()}catch(error){console.error('Failed to start business trip:',error)}}
async function handleStartPersonalTrip(){try{const latest=await kfePresentationApi.read.latestWorkOdometer();const odometer=Number(latest?.odometer);if(!Number.isFinite(odometer)||odometer<0)throw new Error('Authoritative start odometer is unavailable');await kfePresentationApi.commands.startTrip({trip_type:'PERSONAL',start_odometer_km:odometer});await refreshWorkState()}catch(error){console.error('Failed to start personal trip:',error)}}
async function handleEndShift(){try{const [shift,latest]=await Promise.all([kfePresentationApi.read.getActiveShift(),kfePresentationApi.read.latestWorkOdometer()]);const endOdometer=Number(latest?.odometer);if(!shift?.id||!Number.isFinite(endOdometer)||endOdometer<0)throw new Error('Active shift or authoritative end odometer is unavailable');await kfePresentationApi.commands.endShift({id:shift.id,endOdometer});await refreshAll()}catch(error){console.error('Failed to end shift:',error)}}
async function handleEndBusinessTrip(){try{const [draft,latest]=await Promise.all([kfePresentationApi.read.getActiveTripDraft(),kfePresentationApi.read.latestWorkOdometer()]);const endOdometer=Number(latest?.odometer);if(!draft?.trip_id||!Number.isFinite(endOdometer)||endOdometer<0)throw new Error('Active business trip or authoritative end odometer is unavailable');await kfePresentationApi.commands.endTrip({trip_type:'BUSINESS',trip_id:draft.trip_id,end_odometer_km:endOdometer});await refreshAll()}catch(error){console.error('Failed to end business trip:',error)}}
async function handleEndPersonalTrip(){try{const [draft,latest]=await Promise.all([kfePresentationApi.read.getActiveTripDraft(),kfePresentationApi.read.latestWorkOdometer()]);const endOdometer=Number(latest?.odometer);if(!draft?.trip_id||!Number.isFinite(endOdometer)||endOdometer<0)throw new Error('Active personal trip or authoritative end odometer is unavailable');await kfePresentationApi.commands.endTrip({trip_type:'PERSONAL',trip_id:draft.trip_id,end_odometer_km:endOdometer});await refreshAll()}catch(error){console.error('Failed to end personal trip:',error)}}
async function handleEndDay(){try{await kfePresentationApi.commands.endDay();await refreshAll()}catch(error){console.error('Failed to end day:',error)}}
function handleOnline(){online.value=true}function handleOffline(){online.value=false}
onMounted(()=>{syncRoute();window.addEventListener('hashchange',syncRoute);window.addEventListener('online',handleOnline);window.addEventListener('offline',handleOffline);void loadPerformance();void loadWorkState()})
onUnmounted(()=>{window.removeEventListener('hashchange',syncRoute);window.removeEventListener('online',handleOnline);window.removeEventListener('offline',handleOffline)})
</script>
<template><section class="kfe-workspace" :class="{'work-stage':activeModule==='Work'}" :aria-label="activeModule==='Work'?'Work':undefined" aria-live="polite"><div id="work-viewport" v-show="activeModule==='Work'" class="work-stack"><DayStartCard v-if="currentWorkState==='DAY_START'" :latest-odometer="latestWorkOdometer?.odometer??null" @start-day="handleStartDay"/><template v-else-if="currentWorkState==='SHIFT_WAITING'&&!dayEndSummary?.shiftId"><ShiftWaitingCard @start-shift="handleStartShift" @start-personal-trip="handleStartPersonalTrip"/><WorkOperationsCard :performance="performanceModel" :daily-report="dailyOperationalReport" :odometer="latestWorkOdometer?.odometer??null" :commands="kfePresentationApi.commands" @refresh="refreshAll"/></template><template v-else-if="currentWorkState==='SHIFT_WAITING'"><DayEndCard :summary="dayEndSummary" :day-ended="false" @end-day="handleEndDay"/><WorkOperationsCard :performance="performanceModel" :daily-report="dailyOperationalReport" :odometer="latestWorkOdometer?.odometer??null" :commands="kfePresentationApi.commands" @refresh="refreshAll"/></template><template v-else-if="currentWorkState==='DAY_ENDED'"><WorkSummaryCard :shift-summary="completedShiftSummary" :daily-report="dailyOperationalReport"/><WorkOperationsCard :performance="performanceModel" :daily-report="dailyOperationalReport" :odometer="latestWorkOdometer?.odometer??null" :commands="kfePresentationApi.commands" :capture-enabled="false" @refresh="refreshAll"/></template><template v-else-if="currentWorkState==='SHIFT'"><ShiftCard :shift-metrics="shiftMetrics" @end-shift="handleEndShift" @start-business-trip="handleStartBusinessTrip" @start-personal-trip="handleStartPersonalTrip"/><WorkOperationsCard :performance="performanceModel" :daily-report="dailyOperationalReport" :active-shift-id="shiftMetrics?.shiftId??null" :odometer="latestWorkOdometer?.odometer??null" :commands="kfePresentationApi.commands" @refresh="refreshAll"/></template><template v-else-if="currentWorkState==='PERSONAL_TRIP'"><PersonalTripCard :trip-metrics="personalTripMetrics" @end-personal-trip="handleEndPersonalTrip"/><WorkOperationsCard :performance="performanceModel" :daily-report="dailyOperationalReport" :odometer="latestWorkOdometer?.odometer??null" :commands="kfePresentationApi.commands" @refresh="refreshAll"/></template><template v-else-if="currentWorkState==='BUSINESS_TRIP'"><BusinessTripCard :trip-metrics="businessTripMetrics" @end-business-trip="handleEndBusinessTrip"/><WorkOperationsCard :performance="performanceModel" :daily-report="dailyOperationalReport" :odometer="latestWorkOdometer?.odometer??null" :commands="kfePresentationApi.commands" @refresh="refreshAll"/></template></div><div v-show="activeModule==='Performance'"><PerformanceModuleView :online="online" :performance="performanceModel"/></div><div v-show="activeModule==='Admin'"><AdminModuleView :application="kfePresentationApi" :online="online"/></div></section></template>
<style scoped>.work-stage{width:100%;height:100%;min-height:0;overflow:auto;padding:10px;box-sizing:border-box}.work-stack{display:grid;gap:10px;width:100%;min-height:100%}@media(max-width:480px){.work-stage{padding:8px}}</style>
